SET timezone='UTC';
CREATE FUNCTION test_clock() RETURNS timestamptz LANGUAGE sql AS $$SELECT current_setting('test.clock')::timestamptz$$;
DO $$DECLARE d text;BEGIN SELECT pg_get_functiondef('fn_process_weekly_accounting(uuid)'::regprocedure) INTO d;EXECUTE replace(d,'clock_timestamp()','public.test_clock()');END$$;
SET test.clock='2026-09-14T08:30:00Z';
INSERT INTO unions VALUES(u(1)),(u(2));
INSERT INTO clubs(id) VALUES(u(11)),(u(12)),(u(13));
INSERT INTO union_clubs VALUES(u(1),u(11)),(u(2),u(12));
INSERT INTO union_settlement_floor VALUES(u(1),'2026-09-07T00:00Z'),(u(2),'2026-09-07T00:00Z');
INSERT INTO settlement_periods VALUES(u(21),u(11),u(1),'2026-09-07T07:00Z','2026-09-14T07:00Z'),(u(22),u(12),u(2),'2026-09-07T07:00Z','2026-09-14T07:00Z');
INSERT INTO settlement_invoices(club_id,invoice_type,breakdown,message_sent,status) SELECT club_id,'union_weekly_squareup',jsonb_build_object('union_id',union_id,'period_start',start_at,'period_end',end_at),true,'generated' FROM settlement_periods;
INSERT INTO agents VALUES(u(31),u(131),u(11),100.29,false),(u(32),u(132),u(12),75.39,false),(u(33),u(133),u(11),25.01,false),(u(34),u(134),u(13),5.15,false);
SELECT assert_true((fn_union_settlement_cascade_due()->>'checked')::int=0 AND NOT EXISTS(SELECT 1 FROM effects),'nothing posts before Chicago four AM');
SET test.clock='2026-09-14T09:20:00Z';
SET test.credit_failure='true';
SELECT assert_true(fn_union_weekly_rakeback_close_all(u(1))->>'success'='false','legacy union caller reports full-cascade delivery failure');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM effects) AND NOT EXISTS(SELECT 1 FROM credit_invoices) AND NOT EXISTS(SELECT 1 FROM union_settlement_rounds),'credit notification failure rolls all prior rounds and credit invoices back');
SELECT assert_true((SELECT count(*) FROM union_accounting_runs)=1 AND (SELECT status FROM union_accounting_runs)='failed','exact union scope and durable failure survive rollback');
SELECT assert_true((SELECT result->>'error' FROM union_accounting_runs WHERE union_id=u(1))='invoice notification failed','failure reached the real scoped credit writer and delivery trigger');
SET test.credit_failure='false';
SET test.summary_failure='true';
SELECT assert_true(fn_union_weekly_rakeback_close_all(u(1))->>'success'='false' AND NOT EXISTS(SELECT 1 FROM credit_invoices),'weekly summary failure also rolls credit invoices back');
SELECT assert_true((SELECT result->>'error' FROM union_accounting_runs WHERE union_id=u(1))='summary delivery failed','failure reached the final weekly document publisher');
SET test.summary_failure='false';
INSERT INTO rake_records VALUES(u(50),u(1),1.25,'2026-09-14T06:59:00.123456Z',false,NULL);
INSERT INTO daemon_state VALUES('rakeback_settler','2026-09-14T06:59:00.123456Z',now(),u(49));
SELECT fn_union_weekly_rakeback_close_all(u(1));
SELECT assert_true((SELECT result->>'error' FROM union_accounting_runs WHERE union_id=u(1))='weekly_rake_source_not_fully_accrued','same-microsecond unprocessed rake blocks close');
UPDATE daemon_state SET high_water_mark_id=u(50) WHERE daemon='rakeback_settler';
SELECT assert_true(fn_union_weekly_rakeback_close_all(u(1))->>'success'='true','processed exact source cursor allows complete close');
SELECT assert_true((SELECT count(*) FROM credit_invoices)=2 AND (SELECT sum(debt_owed) FROM credit_invoices)=125.30,'credit invoices use only selected union clubs and exact drawn cents');
SELECT assert_true((SELECT count(*) FROM effects WHERE stage=6)=1 AND (SELECT result->>'accounting_version' FROM union_accounting_runs WHERE union_id=u(1))='2','weekly document and versioned completion share the transaction');
SELECT assert_true((fn_union_weekly_rakeback_close_all(u(1))->>'checked')::int=0 AND (SELECT count(*) FROM credit_invoices)=2,'repeated legacy calls cannot repeat accounting');
SELECT assert_true(fn_settle_club_rakeback_batch(u(11))->>'success'='false','independent player drain refuses union clubs');
INSERT INTO rakeback_periods(club_id,period_start,period_end,status,rakeback_amount) VALUES(u(13),'2026-09-07','2026-09-13','pending',20);
SELECT assert_true(fn_union_settlement_cascade_due()->>'success'='true','shared scheduled caller also handles a standalone club');
SELECT assert_true((SELECT count(*) FROM credit_invoices)=4 AND EXISTS(SELECT 1 FROM daemon_state WHERE daemon='weekly_accounting:'||u(13)::text),'standalone payout and invoice commit with durable weekly result');
SELECT assert_true((SELECT count(*) FROM effects WHERE stage=7)=1 AND (SELECT status FROM rakeback_periods WHERE club_id=u(13))='paid','standalone existing payout rules remain operative');
SET test.is_engine='false';
SELECT assert_true(refuses('SELECT fn_union_settlement_cascade_due()','42501') AND refuses('SELECT fn_union_weekly_rakeback_close_all(u(1))','42501') AND refuses('SELECT fn_process_weekly_accounting(NULL)','42501'),'every coordinator entry refuses untrusted callers');
SELECT assert_true(NOT has_function_privilege('anon','fn_process_weekly_accounting(uuid)','execute') AND NOT has_function_privilege('authenticated','fn_generate_scope_credit_invoices(uuid,timestamptz,timestamptz)','execute'),'internal scope writers are not client RPCs');
SET test.is_engine='true';
DO $calendar$DECLARE f timestamptz;t timestamptz;hours int;n int:=4;j jsonb;BEGIN
 FOR f,t,hours IN SELECT * FROM (VALUES('2026-03-02T08:00Z'::timestamptz,'2026-03-09T07:00Z'::timestamptz,167),('2025-10-27T07:00Z'::timestamptz,'2025-11-03T08:00Z'::timestamptz,169)) v(f,t,h) LOOP
  INSERT INTO unions VALUES(u(n));INSERT INTO clubs(id) VALUES(u(n+10));INSERT INTO union_clubs VALUES(u(n),u(n+10));
  INSERT INTO union_settlement_floor VALUES(u(n),f);INSERT INTO settlement_periods VALUES(u(n+20),u(n+10),u(n),f,t);
  INSERT INTO settlement_invoices(club_id,invoice_type,breakdown,message_sent,status) VALUES(u(n+10),'union_weekly_squareup',jsonb_build_object('union_id',u(n),'period_start',f,'period_end',t),true,'generated');
  PERFORM set_config('test.clock',(fn_union_accounting_run_at(t)+interval '20 minutes')::text,true);
  j:=fn_process_weekly_accounting(u(n));
  PERFORM assert_true(j->>'success'='true' AND (j->>'checked')::int=1,'current coordinator completes the daylight-saving boundary week');
  PERFORM assert_true(EXISTS(SELECT 1 FROM union_accounting_runs WHERE union_id=u(n) AND period_start=f AND period_end=t AND extract(epoch FROM period_end-period_start)/3600=hours),'current coordinator preserves 167 and 169 hour earning weeks');
  n:=n+1;
 END LOOP;
END $calendar$;
